children.text:
@font-face {
    font-family: 'Ahem';
    src: url('file:///Users/henryluo/Projects/lambda-test/layout/data/support/ahem3.ttf') format('truetype');
    font-weight: normal;
    font-style: normal;
}

body {
  font-size: 14px;
  line-height: 22px;
  background: #f4f4f4 url(docs/images/background.png);
  color: #000;
  font-family: Helvetica Neue, Helvetica, Arial;
}
.interface {
  font-family: "Lucida Grande", "Lucida Sans Unicode", Helvetica, Arial, sans-serif !important;
}
.container{
  margin-top:50px;
}
div#sidebar {
  background: #fff;
  position: fixed;
  top: 0; left: 0; bottom: 0;
  width: 220px;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  padding: 15px 0 30px 30px;
  border-right: 1px solid #bbb;
  box-shadow: 0 0 20px #ccc; -webkit-box-shadow: 0 0 20px #ccc; -moz-box-shadow: 0 0 20px #ccc;
}
a.toc_title, a.toc_title:visited {
  display: block;
  color: black;
  font-weight: bold;
  margin-top: 15px;
}
  a.toc_title:hover {
    text-decoration: underline;
  }
  #sidebar .version {
    font-size: 10px;
    font-weight: normal;
  }
ul.toc_section {
  font-size: 11px;
  line-height: 14px;
  margin: 5px 0 0 0;
  padding-left: 0px;
  list-style-type: none;
  font-family: Lucida Grande;
}
  .toc_section li {
    cursor: pointer;
    margin: 0 0 3px 0;
  }
    .toc_section li a {
      text-decoration: none;
      color: black;
    }
      .toc_section li a:hover {
        text-decoration: underline;
      }
input#function_filter {
    width: 80%;
}
div.container {
  width: 550px;
  margin: 40px 0 50px 280px;
}
img#logo {
  width: 396px;
  height: 69px;
}
div.warning {
  margin-top: 15px;
  font: bold 11px Arial;
  color: #770000;
}
p {
  margin: 20px 0;
  width: 550px;
}
a, a:visited {
  color: #444;
}
a:active, a:hover {
  color: #000;
}
h1, h2, h3, h4, h5, h6 {
  padding-top: 20px;
}
  h2 {
    font-size: 20px;
  }
b.header {
  font-size: 16px;
  line-height: 30px;
}
span.alias {
  font-size: 14px;
  font-style: italic;
  margin-left: 20px;
}
a.source {
  font-variant: small-caps;
  margin-left: 20px;
}
  a.source + a.source {
    margin-left: unset;
  }
table, tr, td {
  margin: 0; padding: 0;
}
  td {
    padding: 2px 12px 2px 0;
  }
  table .rule {
    height: 1px;
    background: #ccc;
    margin: 5px 0;
  }
  table .dl-link {
    white-space: nowrap;
  }
ul {
  list-style-type: circle;
  padding: 0 0 0 20px;
}
  li {
    margin-bottom: 10px;
  }
  code, pre, tt {
    font-family: Monaco, Consolas, "Lucida Console", monospace;
    font-size: 12px;
    line-height: 18px;
    font-style: normal;
  }
    tt {
      padding: 0px 3px;
      background: #fff;
      border: 1px solid #ddd;
      zoom: 1;
    }
    code {
      margin-left: 20px;
    }
    pre {
      font-size: 12px;
      padding: 2px 0 2px 15px;
      border-left: 5px solid #bbb;
      margin: 0px 0 30px;
    }
input[type=checkbox] {
  position: absolute;
  top: -9999px;
  left: -9999px;
}
label {
  position: fixed;
  left:0;
  display:none;
  width: 1em;
  height: 1.5em;
  padding: .5em 0.5em 0;
  font-size:1.1em;
  color:#fff;
  transition:color .3s ease-in-out;
  cursor: pointer;
  user-select:none;
  margin:0;
  background:rgba(0, 0, 0, 1);
}
.overlay {
  height: 100%;
  width: 0;
  position: fixed;
  z-index: 1;
  top: 0;
  left: 0;
  background-color: rgb(0,0,0);
  background-color: rgba(0,0,0, 0.9);
  overflow-x: hidden;
  transition: 0.5s;
}

@media only screen and (-webkit-min-device-pixel-ratio: 1.5) and (max-width: 640px),
      only screen and (-o-min-device-pixel-ratio: 3/2) and (max-width: 640px),
      only screen and (min-device-pixel-ratio: 1.5) and (max-width: 640px) {
  img {
    max-width: 100%;
  }
  div#sidebar {
    -webkit-overflow-scrolling: initial;
    position: relative;
    width: 100%;
    height: 100%;
    left: 0;
    padding: 20px 0 10px 45px;
    border: 0;
  }
  img#logo {
    width: auto;
    height: auto;
  }
  div.container {
    margin: 50px 0;
    width: 100%;

  }
  p, div.container ul {
    max-width: 98%;
    overflow-x: scroll;
  }
  pre {
    overflow: scroll;
  }
}

@media screen and (max-width: 640px){
  body{
    line-height: 22px;
  }
  ul.toc_section {
    font-size: 14px;
    line-height: 15px;
    font-family: Helvetica Neue, Helvetica, Arial;
  }
  label {
    display:block;
    top:0;
    z-index:999;
  }
  label:after {
    position: absolute;
    right: .25em;
    top: 5px;
    content:"\2261";
    font-size:1.8em;
  }
  label:hover,
  input:checked ~ label {
    color:#fff;
  }
  input:checked ~ #myNav{
    width:0;
  }
  #myNav{
    width: 100%;
  }
  .overlay-content {
    position: relative;
    top: 25%;
    width: 100%;
  }
}

@media screen and (prefers-color-scheme: dark) {
  body {
    background: #111 !important;
    color: #c6c6c6;
  }
  div#sidebar {
    background: #111;
    border-right: 1px solid #666;
    box-shadow: 0 0 20px #555;
    -webkit-box-shadow: 0 0 20px #555;
    -moz-box-shadow: 0 0 20px #555;
  }
  a.toc_title,
  a.toc_title:visited {
    color: #f4f4f4;
  }
  a.toc_title:hover {
    text-decoration: underline;
  }
  .toc_section li a {
    text-decoration: none;
    color: #f4f4f4;
  }
  img#logo {
    filter: invert(1) hue-rotate(180deg) brightness(0.9);
  }
  div.warning {
    color: #CC6060;
  }
  a,
  a:visited {
    color: #f4f4f4;
  }
  a:active,
  a:hover {
    color: #ffffff;
  }
  table .rule {
    background: #777;
  }
  tt {
    background: #444;
    border: 1px solid #777;
  }
  pre {
    border-left: 5px solid #aaa;
  }
}

var myNav = document.getElementById("myNav")
var menu = document.getElementById('menu')
myNav.addEventListener('click',(e)=>{
  if(e.target.tagName=="A"){
    menu.checked = true
  }
})
